BugKu-MISC-1和0的故事题目
思路这一眼就知道是二进制转二维码，把0转成白色，1转成黑色拿ai跑个脚本（注：这是不被允许的，但是这是做题）
#!/usr/bin/env python3# -*- coding: utf-8 -*-&quot;&quot;&quot;把0/1矩阵转成二维码样式图片：- 1 = 黑色- 0 = 白色- 自动在左上、左下、右上添加 Finder Pattern&quot;&quot;&quot;import argparsefrom PIL import Image, ImageOpsdef read_matrix_from_file(path):    with open(path, &quot;r&quot;, encoding=&quot;utf-8&quot;) as f:        lines = [line.strip().replace(&quot; &quot;, &quot;&quot;) for line in f if line.strip()]    if not lines:        raise ValueError(&quot;输入文件为空！&quot;)    width = len(lines[0])    for i, row in enumerate(lines, 1):        if len(row) != width:            raise ValueError(f&quot;第 &#123;i&#125; 行长度 &#123;len(row)&#125; 与首行 &#123;width&#125; 不一致&quot;)        if any(c not in &quot;01&quot; for c in row):            raise ValueError(f&quot;第 &#123;i&#125; 行含有非法字符：&#123;row&#125;&quot;)    return [[c == &quot;1&quot; for c in row] for row in lines]def add_finder_patterns(matrix):    &quot;&quot;&quot;在左上、左下、右上加上7x7的finder pattern&quot;&quot;&quot;    rows, cols = len(matrix), len(matrix[0])    def put_finder(r0, c0):        for r in range(7):            for c in range(7):                rr, cc = r0 + r, c0 + c                if rr &gt;= rows or cc &gt;= cols:                    continue                # Finder pattern 规则                if (                    r in [0, 6]                    or c in [0, 6]                    or (2 &lt;= r &lt;= 4 and 2 &lt;= c &lt;= 4)                ):                    matrix[rr][cc] = True  # 黑                else:                    matrix[rr][cc] = False  # 白    put_finder(0, 0)             # 左上    put_finder(rows - 7, 0)      # 左下    put_finder(0, cols - 7)      # 右上    return matrixdef matrix_to_image(matrix, scale=10, margin=4):    rows, cols = len(matrix), len(matrix[0])    flat_bits = []    for row in matrix:        for v in row:            flat_bits.append(0 if v else 1)  # 黑=0 白=1    base = Image.new(&quot;1&quot;, (cols, rows))    base.putdata(flat_bits)    img = base.resize((cols * scale, rows * scale), resample=Image.NEAREST)    if margin &gt; 0:        border_px = margin * scale        img = ImageOps.expand(img, border=border_px, fill=1)    return img.convert(&quot;L&quot;)def main():    parser = argparse.ArgumentParser(description=&quot;0/1矩阵转二维码样式PNG&quot;)    parser.add_argument(&quot;-i&quot;, &quot;--input&quot;, required=True, help=&quot;输入矩阵文件（文本，包含0和1）&quot;)    parser.add_argument(&quot;-o&quot;, &quot;--output&quot;, default=&quot;qr.png&quot;, help=&quot;输出PNG文件名&quot;)    parser.add_argument(&quot;--scale&quot;, type=int, default=10, help=&quot;每个模块像素大小&quot;)    parser.add_argument(&quot;--margin&quot;, type=int, default=4, help=&quot;外边距模块数&quot;)    args = parser.parse_args()    matrix = read_matrix_from_file(args.input)    matrix = add_finder_patterns(matrix)    img = matrix_to_image(matrix, scale=args.scale, margin=args.margin)    img.save(args.output)    print(f&quot;✅ 已生成二维码样式图：&#123;args.output&#125;&quot;)if __name__ == &quot;__main__&quot;:    main()

输入指令然后扫码就可以得到flag了
python bin2qr_with_finder.py -i 1和0的故事.txt -o qr.png --scale 20


